Variant Forma
  Case Circulo(radio As Integer)
  Case Rectangulo(ancho As Integer, alto As Integer)
  Case Punto
EndVariant
Subroutine area(f As Forma) As Integer
  Define total As Integer <- 0;
  Switch f Do
    Forma.Circulo(r): total <- 3 * r * r;
    Forma.Rectangulo(a, h): total <- a * h;
    Forma.Punto: total <- 0;
  EndSwitch
  Return total;
EndSubroutine
Algorithm Areas
  Write area(Forma.Circulo(1));
  Write area(Forma.Rectangulo(3, 4));
  Write area(Forma.Punto);
EndAlgorithm
